   nc=nc+1; if(lo_tkx_del_slot!==fo_tkx_del_slot)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=tkx_del_slot cyc=%0d",cyc); end
   nc=nc+1; if(lo_tkx_del_valid!==fo_tkx_del_valid)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=tkx_del_valid cyc=%0d",cyc); end
   nc=nc+1; if(lo_tkx_del_flit!==fo_tkx_del_flit)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=tkx_del_flit cyc=%0d",cyc); end
   nc=nc+1; if(lo_fault!==fo_fault)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=fault cyc=%0d",cyc); end
   nc=nc+1; if(lo_fault_cause!==fo_fault_cause)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=fault_cause cyc=%0d",cyc); end
   nc=nc+1; if(lo_done!==fo_done)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=done cyc=%0d",cyc); end
   nc=nc+1; if(lo_stat_cycles!==fo_stat_cycles)begin bad=bad+1; if(bad<=5)$display("EQ_MISMATCH port=stat_cycles cyc=%0d",cyc); end
  end
 end
 task lp_finish; input [8*48-1:0] what; begin
  if(bad==0&&nc>0)$display("LPF_EQ PASS compared=%0d cycles=%0d stimulus=%0s",nc,cyc,what);
  else $display("LPF_EQ FAIL mismatches=%0d of %0d stimulus=%0s",bad,nc,what);
  $finish; end endtask
 `include "rtl/hbm_accel/generic/collective/p2p/landed/stim_q3_lp_ar.vh"
endmodule
